from typing import List

class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []
        d = {
            "2": "abc",
            "3": "def",
            "4": "ghi",
            "5": "jkl",
            "6": "mno",
            "7": "pqrs",
            "8": "tuv",
            "9": "wxyz",
        }
        n = len(digits)
        ans = []
        for i in range(1 << n):
            s = []
            for j in range(n):
                if i >> j & 1:
                    s.append(d[digits[j]])
            ans.append("".join(s))
        return ans
