from typing import List

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        cnt = 0
        for x in nums:
            if cnt == 0:
                cnt += 1
                continue
            if x == nums[cnt - 1]:
                cnt += 1
            else:
                cnt -= 1
        return nums[cnt]
