class Solution:
    def isHappy(self, n: int) -> bool:
        s = set()
        while n not in s:
            s.add(n)
            n = self.calc(n)
        return n == 1
    def calc(self, n: int) -> int:
        ans = 0
        while n:
            ans += (n % 10) ** 2
            n //= 10
        return ans
