from collections import defaultdict

class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        d1 = defaultdict(int)
        d2 = defaultdict(int)
        for a, b in zip(s, t):
            if (a not in d1 and b in d2) or (a in d1 and b not in d2):
                return False
            if (a in d1 and d1[a] != b) or (a not in d1 and d2[b] != a):
                return False
            d1[a] = b
            d2[b] = a
        return True
```

